// Type-bestemmelse ud fra kontonummer (se header-dokumentation)
function inferType(num: number): StandardAccountType {
  if (num >= 1000 && num <= 3999) {
    if (num >= 3191 && num <= 3999) return 'FINANCIAL';
    return 'EXPENSE';
  }
  if (num >= 5000 && num <= 6499) return 'ASSET';
  if (num >= 6500 && num <= 6999) return 'EQUITY';
  if (num >= 7000 && num <= 7999) return 'LIABILITY';
  if (num >= 8000 && num <= 8999) return 'YEAR_END';
  return 'STATISTICAL';
}

