/**
 * Officiel Standardkontoplan (version 20260101) — 603 konti.
 * Eksporteret i det format som StandardAccount-interfacet forventer.
 * Brug denne i stedet for det gamle manuelle PUBLIC_STANDARD_CHART-array.
 */
export const OFFICIAL_STANDARD_CHART: StandardAccount[] = ALL_ACCOUNTS.map((a) => ({
  number: a.number.toString(),
  name: a.name,
  nameEn: a.name, // Officiel JSON har kun danske navne
  type: a.type,
  description: a.isHeader ? `Hovedkonto: ${a.name}` : (a.parentGroup ? `Underkonto til ${a.parentGroup}: ${a.name}` : a.name),
  suggestedFSR: FSR_SUGGESTIONS[a.number],
}));

/** Summeret antal konti i den officielle standardkontoplan. */
export const OFFICIAL_CHART_COUNT = OFFICIAL_STANDARD_CHART.length;